registry = ClientRegistry()


def _make_timestamp():
    return datetime.now(timezone.utc).isoformat()


class BaseTransport(ABC):
    @abstractmethod
    async def on_connect(self, connection) -> str:
        ...

    @abstractmethod
    async def on_disconnect(self, client_id: str):
        ...

    @abstractmethod
    async def send_message(self, client_id: str, message: dict):
        ...

    @abstractmethod
    async def broadcast(self, message: dict):
        ...


class WebSocketTransport(BaseTransport):
    async def on_connect(self, websocket) -> str:
        client_id = registry.add(websocket)
        welcome = {
            "type": "system",
            "payload": {"client_id": client_id, "message": "connected"},
            "timestamp": _make_timestamp(),
        }
        await websocket.send(json.dumps(welcome))
        return client_id

    async def on_disconnect(self, client_id: str):
        registry.remove(client_id)

    async def send_message(self, client_id: str, message: dict):
        ws = registry.get_all().get(client_id)
        if ws is not None:
            try:
                await ws.send(json.dumps(message))
            except Exception:
                pass

    async def broadcast(self, message: dict):
        message_str = json.dumps(message)
        clients = registry.get_all()
        tasks = [asyncio.create_task(ws.send(message_str)) for ws in clients.values()]
        if tasks:
            await asyncio.gather(*tasks, return_exceptions=True)


def _get_transport() -> BaseTransport:
    global _transport
    if _transport is None:
        transport_type = os.environ.get("TRANSPORT", "websocket").lower()
        if transport_type == "websocket":
            _transport = WebSocketTransport()
        else:
            raise ValueError(f"Unknown TRANSPORT: {transport_type}")
    return _transport


class NotificationServer:
    def __init__(self, transport: BaseTransport):
        self._transport = transport

    async def handle_connect(self, connection) -> str:
        return await self._transport.on_connect(connection)

    async def handle_disconnect(self, client_id: str):
        await self._transport.on_disconnect(client_id)
        await _broadcast(
            {
                "type": "system",
                "payload": {"client_id": client_id, "message": "disconnected"},
                "timestamp": _make_timestamp(),
            }
        )

    async def handle_message(self, client_id: str, data: dict):
        msg_type = data.get("type", "broadcast")
        payload = data.get("payload", {})
        timestamp = _make_timestamp()

        if msg_type == "subscribe":
            channel = data.get("channel")
            if channel:
                registry.subscribe(client_id, channel)
                await self._transport.send_message(
                    client_id,
                    {
                        "type": "system",
                        "payload": {
                            "message": f"subscribed to {channel}",
                            "channel": channel,
                        },
                        "timestamp": timestamp,
                    },
                )
        elif msg_type == "unsubscribe":
            channel = data.get("channel")
            if channel:
                registry.unsubscribe(client_id, channel)
                await self._transport.send_message(
                    client_id,
                    {
                        "type": "system",
                        "payload": {
                            "message": f"unsubscribed from {channel}",
                            "channel": channel,
                        },
                        "timestamp": timestamp,
                    },
                )
        elif msg_type == "direct":
            target = payload.get("target")
            if target is not None:
                await _send_direct(
                    target,
                    {
                        "type": "direct",
                        "payload": {
                            "from": client_id,
                            "message": payload.get("message", {}),
                        },
                        "timestamp": timestamp,
                    },
                )
        else:
            channel = data.get("channel")
            message = {
                "type": msg_type,
                "payload": {"from": client_id, **payload},
                "timestamp": timestamp,
            }
            if channel:
                await _broadcast_to_channel(channel, message)
            else:
                await _broadcast(message)


async def _init_redis():
    global _redis
    if _redis is None:
        _redis = aioredis.from_url(REDIS_URL, decode_responses=True)
    return _redis


async def _init_db():
    global _db
    if _db is None:
        _db = await aiosqlite.connect(DATABASE_URL)
        await _db.execute(
            """
            CREATE TABLE IF NOT EXISTS messages (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                channel TEXT,
                type TEXT NOT NULL,
                payload TEXT NOT NULL,
                timestamp TEXT NOT NULL
            )
            """
        )
        await _db.commit()
    return _db


async def _check_rate_limit(client_id):
    r = await _init_redis()
    key = f"ws:ratelimit:{client_id}"
    count = await r.incr(key)
    if count == 1:
        await r.expire(key, 60)
    return count > RATE_LIMIT


async def _expire_loop():
    while True:
        db = await _init_db()
        cutoff = (datetime.now(timezone.utc) - timedelta(days=MESSAGE_TTL_DAYS)).isoformat()
