async def handler(websocket):
    transport = _get_transport()
    server = NotificationServer(transport)
    client_id = await server.handle_connect(websocket)
    try:
        async for raw in websocket:
            try:
                data = json.loads(raw)
            except json.JSONDecodeError:
                continue
            if await _check_rate_limit(client_id):
                await transport.send_message(
                    client_id,
                    {
                        "type": "system",
                        "payload": {"error": True, "message": "rate limit exceeded"},
                        "timestamp": _make_timestamp(),
                    },
                )
                continue
            await server.handle_message(client_id, data)
