async def process_request(connection, request):
    if request.path == "/health":
        body = json.dumps({"connected_clients": registry.count}).encode()
        headers = Headers({"Content-Type": "application/json"})
        return Response(200, "OK", headers, body)

    if request.path == "/channels":
        body = json.dumps(registry.get_channels()).encode()
        headers = Headers({"Content-Type": "application/json"})
        return Response(200, "OK", headers, body)

    if request.path.startswith("/history"):
        limit = 50
        channel = None
        since = None
        parsed = urlparse(request.path)
        if parsed.query:
            params = parse_qs(parsed.query)
            if "limit" in params:
                limit = int(params["limit"][0])
            if "channel" in params:
                channel = params["channel"][0]
            if "since" in params:
                since = params["since"][0]

        db = await _init_db()
        where_clauses = []
        where_params = []

        if channel is not None:
            where_clauses.append("channel = ?")
            where_params.append(channel)
        if since is not None:
            where_clauses.append("timestamp >= ?")
            where_params.append(since)

        where_sql = ""
        if where_clauses:
            where_sql = "WHERE " + " AND ".join(where_clauses)

        rows = await db.execute_fetchall(
            f"SELECT id, channel, type, payload, timestamp FROM messages {where_sql} ORDER BY timestamp ASC LIMIT ?",
            (*where_params, limit + 1),
        )

        has_more = len(rows) > limit
        if has_more:
            rows = rows[:limit]

        messages = [
            {
                "id": row[0],
                "channel": row[1],
                "type": row[2],
                "payload": json.loads(row[3]),
                "timestamp": row[4],
            }
            for row in rows
        ]
        body = json.dumps({"messages": messages, "has_more": has_more}).encode()
        headers = Headers({"Content-Type": "application/json"})
        return Response(200, "OK", headers, body)

    if request.path.startswith("/messages"):
        limit = 50
        offset = 0
        parsed = urlparse(request.path)
        if parsed.query:
            params = parse_qs(parsed.query)
            if "limit" in params:
                limit = int(params["limit"][0])
            if "offset" in params:
                offset = int(params["offset"][0])

        db = await _init_db()
        rows = await db.execute_fetchall(
            "SELECT id, channel, type, payload, timestamp FROM messages ORDER BY id DESC LIMIT ? OFFSET ?",
            (limit, offset),
        )
        messages = [
            {
                "id": row[0],
                "channel": row[1],
                "type": row[2],
                "payload": json.loads(row[3]),
                "timestamp": row[4],
            }
            for row in rows
        ]
        body = json.dumps(messages).encode()
        headers = Headers({"Content-Type": "application/json"})
        return Response(200, "OK", headers, body)

    if request.path.startswith("/channels/"):
        parts = request.path.split("/")
        if len(parts) >= 4 and parts[3] == "subscribers":
            channel_name = parts[2]
            subscribers = registry.get_subscribers(channel_name)
            body = json.dumps(
                {"channel": channel_name, "subscribers": list(subscribers)}
            ).encode()
            headers = Headers({"Content-Type": "application/json"})
            return Response(200, "OK", headers, body)

    return None


async def start_server(host="0.0.0.0", port=8765):
    await _start_background()
    try:
        async with serve(
            handler,
            host,
            port,
            process_request=process_request,
        ) as server_inst:
            await server_inst.serve_forever()
    finally:
        await _stop_background()


if __name__ == "__main__":
    asyncio.run(start_server())

